package com.adib.maintenance;
import android.content.Context;import android.os.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
final class EmployeeChats {
 interface Done{void done(JSONObject value,String error);}
 static final TaskReminderActions.Transport DEFAULT_TRANSPORT=(m,p,b)->TaskManagementActivity.httpWithTimeout(m,p,b,25000);
 static TaskReminderActions.Transport transport=DEFAULT_TRANSPORT;
 static final ExecutorService IO=Executors.newSingleThreadExecutor();static String owner="";static JSONObject directory=new JSONObject();static final Map<String,JSONObject> chats=new LinkedHashMap<>();static final Map<String,String> operations=new HashMap<>();static boolean refreshing;static final List<Done> waiters=new ArrayList<>();
 static boolean isEmployee(String id){return id!=null&&id.startsWith("employee:");}
 static void scope(Context c){String now=DirectConfig.scope(c);if(!owner.equals(now)){owner=now;directory=new JSONObject();chats.clear();operations.clear();}}
 static JSONArray tasks(JSONArray rows){JSONArray out=new JSONArray();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject t=rows.optJSONObject(i);if(t!=null&&!isEmployee(t.optString("taskId")))out.put(t);}return out;}
 static JSONArray merge(Context c,JSONArray rows){scope(c);JSONArray out=tasks(rows);for(JSONObject t:chats.values())out.put(t);return out;}
 static JSONArray peers(Context c){scope(c);JSONArray p=directory.optJSONArray("employees");return p==null?new JSONArray():p;}
 static JSONObject comment(JSONObject m)throws Exception{return new JSONObject(m.toString()).put("direct",true).put("authorName",m.optString("senderName")).put("authorId",m.optString("senderId")).put("createdAt",new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.US){{setTimeZone(TimeZone.getTimeZone("UTC"));}}.format(new Date(m.optLong("createdAt"))));}
 static JSONObject thread(String id,String name,JSONArray comments)throws Exception{return new JSONObject().put("taskId","employee:"+id).put("peerId",id).put("title",name).put("source","Əməkdaş").put("isEmployee",true).put("comments",comments).put("unreadCount",0);}
 static void call(Context c,String method,String path,JSONObject body,Done done){scope(c);String scoped=owner;if(Boolean.getBoolean("adib.testing")&&transport==DEFAULT_TRANSPORT){done.done(new JSONObject(),"");return;}if(DirectRuntime.enabled()){done.done(null,"Əməkdaşlarla söhbət üçün server rejimi və ADIB hesabı lazımdır");return;}IO.execute(()->{JSONObject r=null;String e="";try{r=transport.request(method,path,body);if(r==null)throw new Exception("Server cavabı alınmadı");}catch(Exception ex){e=ex.getMessage();}JSONObject reply=r;String error=e;new Handler(Looper.getMainLooper()).post(()->{if(!scoped.equals(DirectConfig.scope(c))){done.done(null,"Profil dəyişib");return;}done.done(reply,error);});});}
 static void refresh(Context c,Done done){scope(c);waiters.add(done);if(refreshing)return;refreshing=true;call(c,"GET","/api/employee-chats",null,(r,e)->{refreshing=false;if(r!=null){directory=r;Set<String> peers=new HashSet<>();JSONArray people=r.optJSONArray("employees");if(people!=null)for(int i=0;i<people.length();i++)peers.add(people.optJSONObject(i).optString("id"));chats.entrySet().removeIf(x->!peers.contains(x.getValue().optString("peerId")));JSONArray rows=r.optJSONArray("threads");if(rows!=null)for(int i=0;i<rows.length();i++)try{JSONObject row=rows.getJSONObject(i),old=chats.get(row.optString("peerId")),last=row.optJSONObject("lastMessage");JSONArray comments=old==null?new JSONArray():old.optJSONArray("comments");boolean same=old!=null&&old.optBoolean("loaded")&&((last==null&&comments.length()==0)||(last!=null&&comments.length()>0&&last.optString("id").equals(comments.optJSONObject(comments.length()-1).optString("id"))));if(!same){comments=new JSONArray();if(last!=null)comments.put(comment(last));}JSONObject t=thread(row.optString("peerId"),row.optString("peerName"),comments).put("unreadCount",row.optInt("unreadCount")).put("loaded",same);chats.put(row.optString("peerId"),t);}catch(Exception ignored){}}List<Done> callbacks=new ArrayList<>(waiters);waiters.clear();for(Done callback:callbacks)callback.done(r,e);});}
 static void load(Context c,String id,Done done){if(!isEmployee(id)){done.done(null,"Yanlış söhbət");return;}String peer=id.substring(9);call(c,"GET","/api/employee-messages?peerId="+android.net.Uri.encode(peer),null,(r,e)->{if(r!=null)try{JSONArray rows=r.getJSONArray("messages"),comments=new JSONArray();for(int i=0;i<rows.length();i++)comments.put(comment(rows.getJSONObject(i)));JSONObject t=thread(peer,r.getJSONObject("peer").optString("name"),comments).put("loaded",true);chats.put(peer,t);}catch(Exception ex){r=null;e=ex.getMessage();}done.done(r,e);});}
 static void send(Context c,String id,String text,Done done){scope(c);String key=id+"|"+text;String op=operations.computeIfAbsent(key,k->UUID.randomUUID().toString());try{JSONObject b=new JSONObject().put("peerId",id.substring(9)).put("text",text).put("operationId",op);call(c,"POST","/api/employee-messages",b,(r,e)->{if(r!=null)try{JSONObject msg=comment(r.getJSONObject("message")),t=chats.get(id.substring(9));if(t!=null){JSONArray rows=t.optJSONArray("comments");if(rows==null)rows=new JSONArray();boolean found=false;for(int i=0;i<rows.length();i++)if(msg.optString("id").equals(rows.optJSONObject(i).optString("id")))found=true;if(!found)rows.put(msg);t.put("comments",rows);}operations.remove(key);done.done(r,"");}catch(Exception ex){done.done(null,ex.getMessage());}else done.done(null,e);});}catch(Exception ex){done.done(null,ex.getMessage());}}
}
